// scenarioOptions returns per-scenario Options additions; merged on top
// of the WithFS+WithFolder+WithNow base.
func scenarioOptions(scenario string) []Option {
	switch scenario {
	case "template_model":
		return []Option{WithModel(map[string]any{
			"app": map[string]any{"name": "Acme", "version": "1.0.0"},
		})}
	case "copy_file", "copy_in_file", "inject_fragment_child", "inject_copy_child",
		"frag_nonslot_no_default_error", "frag_template_error", "frag_reads_generated",
		"frag_slot_copy", "frag_replace_fn_emits", "frag_indent_bool", "copy_in_file_replace":
		return []Option{WithModel(map[string]any{"name": "World"})}
	case "folder_and_project_in_file", "replace_values":
		return []Option{WithModel(map[string]any{"name": "N"})}
	case "frag_double_template":
		return []Option{WithModel(map[string]any{"a": "$$b$$", "b": "X", "name": "N"})}
	case "preserve_mode", "dotfile_preserve":
		t := true
		return []Option{WithExisting(Existing{Txt: ExistingTxt{Preserve: &t}})}
	case "binary_copy_identical_no_backup":
		t := true
		return []Option{WithExisting(Existing{Bin: ExistingBin{Preserve: &t}})}
	case "present_mode":
		t := true
		return []Option{WithExisting(Existing{Txt: ExistingTxt{Present: &t}})}
	case "diff_mode":
		t := true
		return []Option{WithExisting(Existing{Txt: ExistingTxt{Diff: &t}})}
	case "preserve_and_diff":
		t := true
		return []Option{WithExisting(Existing{Txt: ExistingTxt{Preserve: &t, Diff: &t}})}
	case "protect_and_present":
		t, f := true, false
		return []Option{WithExisting(Existing{Txt: ExistingTxt{Write: &f, Present: &t}})}
	case "basic_copy":
		return []Option{WithModel(map[string]any{"x": map[string]any{"y": "Y", "z": "Z"}})}
	case "copy_ignore_text", "copy_binary_unlisted_ext":
		return []Option{WithModel(map[string]any{"v": "V"})}
	case "existing_bin_classification":
		t := true
		return []Option{
			WithModel(map[string]any{"v": "V"}),
			WithExisting(Existing{
				Txt: ExistingTxt{Diff: &t},
				Bin: ExistingBin{Preserve: &t},
			}),
		}
	case "absolute_paths":
		return []Option{WithFolder("/top")}
	}
	return nil
}

const frozenNow int64 = 1735689600000

func TestParityScenarios(t *testing.T) {
	entries, err := parityFS.ReadDir("testdata/parity")
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if !strings.HasSuffix(e.Name(), ".json") {
			continue
		}
		name := strings.TrimSuffix(e.Name(), ".json")
		// Phase-shaped corpora are owned by their dedicated test functions
		// (e.g. merge_retain.json drives TestMergeRetainSequence). They
		// don't fit the {opts, prepopulate, vol} runner shape.
		if _, isPhaseShaped := phaseShapedCorpora[name]; isPhaseShaped {
			continue
		}
		t.Run(name, func(t *testing.T) {
			runParityCase(t, "testdata/parity/"+e.Name(), name)
		})
	}
}

func runParityCase(t *testing.T, path, name string) {
	t.Helper()
	body, err := parityFS.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var c parityCase
	if err := json.Unmarshal(body, &c); err != nil {
		t.Fatalf("decode %s: %v", path, err)
	}

	// Multi-phase scenarios live in scenarioMultiPhase and own their
	// own MemFS lifecycle.
	if mp, ok := scenarioMultiPhase[name]; ok {
		mem := mp(t)
		assertVol(t, mem, c.Vol)
		return
	}

	runner, ok := scenarioRunners[name]
	if !ok {
		if reason, known := knownParityGaps[name]; known {
			t.Skipf("known parity gap: %s", reason)
			return
		}
		// A missing runner is a parity gap, not a non-event: the TS side has
		// a scenario the Go port does not answer for. Fail loudly, and use
		// knownParityGaps to carry a deliberate, documented exemption.
		t.Fatalf("scenario %s has no Go runner; add one to scenarioRunners "+
			"(or record a deliberate exemption in knownParityGaps)", name)
		return
	}

	mem := NewMemFS()
	for k, v := range c.Prepopulate {
		_ = mem.WriteFile(k, []byte(v))
	}

	opts := []Option{WithFS(mem), WithFolder("/out"), WithNow(func() int64 { return frozenNow })}
	opts = append(opts, scenarioOptions(name)...)
	j := New(opts...)

	res, gerr := j.Generate(Options{}, runner)

	if c.Error {
		if gerr == nil {
			t.Fatalf("TS failed but Go succeeded")
		}
		if got := parityErrorBody(gerr); got != c.ErrorBody {
			t.Errorf("error body\n got %q\nwant %q", got, c.ErrorBody)
		}
	} else if gerr != nil {
		t.Fatalf("TS succeeded but Go failed: %v", gerr)
	}

	if c.Files != nil {
		assertFiles(t, res.Files, *c.Files)
	}
	if c.Audit != nil {
		assertAudit(t, res.Audit(), c.Audit)
	}
	assertVol(t, mem, c.Vol)
}

// parityErrorBody is the part of a Go refusal the corpus records: the
// NodeError's own message, with an embedded filesystem error cut to
// `(threw: <os>)`, as extract-parity.js cuts TS's.
func parityErrorBody(err error) string {
	body := err.Error()
	var ne *NodeError
	if errors.As(err, &ne) {
		body = ne.Err.Error()
	}
	if i := strings.Index(body, "(threw: "); i >= 0 {
		body = body[:i] + "(threw: <os>)"
	}
	return body
}

// auditJSON renders a Go audit trail in the recorded [tag, data] form. An
// err compares by presence only: its text is the host's.
func auditJSON(t *testing.T, a Audit) []any {
	t.Helper()
	out := make([]any, 0, len(a))
	for _, e := range a {
		data := map[string]any{}
		for k, v := range e.Data {
			if k == "err" {
				v = "<err>"
			}
			data[k] = v
		}
		out = append(out, []any{e.Tag, data})
	}
	b, err := json.Marshal(out)
	if err != nil {
		t.Fatal(err)
	}
	var norm []any
	_ = json.Unmarshal(b, &norm)
	return norm
}

// auditPair renders a Go audit trail and a recorded TS one comparably,
// entry by entry and in order, each err compared by presence.
func auditPair(t *testing.T, got Audit, want []any) (string, string) {
	t.Helper()
	for _, e := range want {
		pair, _ := e.([]any)
		if len(pair) == 2 {
			if data, ok := pair[1].(map[string]any); ok {
				if _, has := data["err"]; has {
					data["err"] = "<err>"
				}
			}
		}
	}
	gb, _ := json.Marshal(auditJSON(t, got))
	wb, _ := json.Marshal(want)
	return string(gb), string(wb)
}

// assertAudit compares a Go audit trail with the recorded TS one.
func assertAudit(t *testing.T, got Audit, want []any) {
	t.Helper()
	if g, w := auditPair(t, got, want); g != w {
		t.Errorf("audit differs\nGo: %s\nTS: %s", g, w)
	}
}

// assertFiles compares the seven files lists with the TS run's, in order.
func assertFiles(t *testing.T, got, want Files) {
	t.Helper()
	g, _ := json.Marshal(got.listed())
	w, _ := json.Marshal(want.listed())
	if string(g) != string(w) {
		t.Errorf("files lists differ\nGo: %s\nTS: %s", g, w)
	}
}

func assertVol(t *testing.T, mem *MemFS, want map[string]corpusBytes) {
	t.Helper()
	gotS := mem.Vol()

	missing := []string{}
	mismatched := []string{}
	kind := []string{}
	for p, w := range want {
		actual, ok := gotS[p]
		if !ok {
			missing = append(missing, p)
			continue
		}
		// A nil value is a DIRECTORY on both sides: TS's toJSON writes null
		// for an empty one and corpusBytes decodes that to nil, while
		// Vol() reports one as nil. bytes.Equal would call it equal to an
		// empty FILE, so the kinds are compared before the bytes. See #41.
		if (actual == nil) != (w == nil) {
			kind = append(kind, p)
			continue
		}
		if !bytes.Equal(actual, w) {
			mismatched = append(mismatched, p)
		}
	}
	extra := []string{}
	for p := range gotS {
		if _, ok := want[p]; !ok {
			extra = append(extra, p)
		}
	}
	sort.Strings(missing)
	sort.Strings(mismatched)
	sort.Strings(extra)
	sort.Strings(kind)

	if len(missing) > 0 {
		t.Errorf("Go output missing %d paths from TS reference: %v", len(missing), missing)
	}
	if len(extra) > 0 {
		t.Errorf("Go output has %d extra paths not in TS reference: %v", len(extra), extra)
	}
	for _, p := range kind {
		t.Errorf("path %s: one stack has a directory where the other has a "+
			"file (Go nil=%v, TS nil=%v)", p, gotS[p] == nil, want[p] == nil)
	}
	for _, p := range mismatched {
		t.Errorf("path %s: bytes differ\nGo:\n%q\nTS:\n%q\n", p, gotS[p], want[p])
	}
}

