// scenarioMultiPhase holds runners that can't be expressed as a single
// Generate call. Each runner builds the FS state (running multiple
// generations + external edits) and returns the MemFS for assertion.
var scenarioMultiPhase = map[string]func(*testing.T) *MemFS{
	"merge_basic": func(t *testing.T) *MemFS { return mergeRunner(t, "AAA\n", "AAA\nuser-line\n", "BBB\n", "$$body$$") },
	"merge_update": func(t *testing.T) *MemFS {
		return mergeRunner(t, "AAA\n", "// header\nAAA\n// user-comment\n", "BBB\n", "// header\n$$body$$")
	},
	"merge_clean": func(t *testing.T) *MemFS { return mergeRunnerNoEdit(t, "AAA\n", "CCC\n", "$$body$$") },
	"merge_no_baseline": func(t *testing.T) *MemFS {
		// User-authored file is in place but no duplicate baseline
		// exists — typical "first run after adopting jostraca on
		// existing code" state. Merge mode without a baseline falls
		// through to the regular write path (TS FileHandler.ts:282-336
		// leaves the merge block silently when dpath doesn't exist).
		mem := NewMemFS()
		_ = mem.WriteFile("/out/sdk/foo.txt", []byte("USER\n"))
		j := New(WithFS(mem), WithFolder("/out"), WithNow(func() int64 { return frozenNow }))
		mergeTrue := true
		_, err := j.Generate(Options{
			Existing: Existing{Txt: ExistingTxt{Merge: &mergeTrue}},
		}, func(j *J) {
			j.Project(ProjectProps{Folder: "sdk"}, func(j *J) {
				j.File("foo.txt", func(j *J) { j.Content("GEN\n") })
			})
		})
		if err != nil {
			t.Fatal(err)
		}
		return mem
	},
	"fragment_subcmp": func(t *testing.T) *MemFS {
		mem := NewMemFS()
		_ = mem.WriteFile("/f01.txt", []byte("TWO-$$a$$-bar-zed-con-foo+<[SLOT]>\n"))
		Foo := func(j *J, arg string) {
			j.Content("FOO[")
			j.Content(arg)
			j.Content("]")
		}
		j := New(WithFS(mem), WithFolder("/out"), WithNow(func() int64 { return frozenNow }), WithModel(map[string]any{"a": "A"}))
		_, err := j.Generate(Options{}, func(j *J) {
			j.Project(ProjectProps{}, func(j *J) {
				j.File("foo.txt", func(j *J) {
					j.Content("ONE\n")
					j.Fragment(FragmentProps{
						From: "/f01.txt",
						Replace: map[string]any{
							"bar": "BAR",
							"zed": func() string { return "ZED" },
							"con": func(j *J) { j.Content("CON") },
							"foo": func(j *J) { Foo(j, "B") },
						},
					}, func(j *J) {
						j.Content("S")
					})
					j.Content("THREE\n")
				})
			})
		})
		if err != nil {
			t.Fatal(err)
		}
		return mem
	},
}

// mergeRunner runs the canonical 2-phase merge scenario: gen A, user
// edit, regen B with merge mode.
func mergeRunner(t *testing.T, bodyA, userEdit, bodyB, srcTpl string) *MemFS {
	t.Helper()
	mem := NewMemFS()
	now := func() int64 { return frozenNow }
	gen := func(body string, opts Options) {
		j := New(WithFS(mem), WithFolder("/out"), WithNow(now), WithModel(map[string]any{"body": body}))
		_, err := j.Generate(opts, func(j *J) {
			j.Project(ProjectProps{Folder: "sdk"}, func(j *J) {
				j.File("foo.txt", func(j *J) { j.Content(srcTpl) })
			})
		})
		if err != nil {
			t.Fatal(err)
		}
	}
	gen(bodyA, Options{})
	_ = mem.WriteFile("/out/sdk/foo.txt", []byte(userEdit))
	mergeTrue := true
	gen(bodyB, Options{Existing: Existing{Txt: ExistingTxt{Merge: &mergeTrue}}})
	return mem
}

// mergeRunnerNoEdit skips the user edit between generations - exercises
// the clean-merge path where existing matches the prior baseline.
func mergeRunnerNoEdit(t *testing.T, bodyA, bodyB, srcTpl string) *MemFS {
	t.Helper()
	mem := NewMemFS()
	now := func() int64 { return frozenNow }
	gen := func(body string, opts Options) {
		j := New(WithFS(mem), WithFolder("/out"), WithNow(now), WithModel(map[string]any{"body": body}))
		_, err := j.Generate(opts, func(j *J) {
			j.Project(ProjectProps{Folder: "sdk"}, func(j *J) {
				j.File("foo.txt", func(j *J) { j.Content(srcTpl) })
			})
		})
		if err != nil {
			t.Fatal(err)
		}
	}
	gen(bodyA, Options{})
	mergeTrue := true
	gen(bodyB, Options{Existing: Existing{Txt: ExistingTxt{Merge: &mergeTrue}}})
	return mem
}

// parityRuns mirrors the multi-generate scenarios recorded by snapshotRuns
// in tools/extract-parity.js. Each step is an edit (a func over the volume)
// or a generate (options and a root).
type parityStep struct {
	edit func(*MemFS)
	opts Options
	root func(*J)
}

func parityOne(name, body string) func(*J) {
	return func(j *J) {
		j.Project(ProjectProps{Folder: "app"}, func(j *J) {
			j.File(name, func(j *J) { j.Content(body) })
		})
	}
}

func parityAuditTree(a, b string) func(*J) {
	return func(j *J) {
		j.Project(ProjectProps{Folder: "app"}, func(j *J) {
			j.File("a.txt", func(j *J) { j.Content(a) })
			j.Folder("sub", func(j *J) {
				j.File("b.txt", func(j *J) { j.Content(b) })
			})
		})
	}
}

var parityRuns = map[string][]parityStep{
	"audit_basic": {{root: parityAuditTree("A\n", "B\n")}},
	"audit_rerun": func() []parityStep {
		yes, no := true, false
		return []parityStep{
			{root: parityAuditTree("L1\nL2\nL3\n", "B\n")},
			{edit: func(m *MemFS) { _ = m.WriteFile("/out/app/a.txt", []byte("L1\nU\nL3\n")) }},
			{opts: Options{Existing: Existing{Txt: ExistingTxt{Merge: &yes, Preserve: &yes}}},
				root: parityAuditTree("L1\nG\nL3\n", "B\n")},
			{opts: Options{Existing: Existing{Txt: ExistingTxt{Write: &no, Present: &yes}}},
				root: parityAuditTree("L1\nG2\nL3\n", "B\n")},
			{opts: Options{Existing: Existing{Txt: ExistingTxt{Diff: &yes}}},
				root: parityAuditTree("L1\nG3\nL3\n", "B\n")},
		}
	}(),
	"audit_nested": {
		{edit: func(m *MemFS) {
			_ = m.WriteFile("/src/tree/t.txt", []byte("T $$v$$\n"))
			_ = m.WriteFile("/src/tree/deep/i.png", []byte{0x89, 0x50, 0x00, 0xff})
			_ = m.WriteFile("/src/tree/deep/m.bin", []byte{0x00, 0x01, 0x02})
			_ = m.WriteFile("/out/app/j.txt", []byte("<\n#--START--#\nold\n#--END--#\n>"))
		}},
		{opts: Options{Model: map[string]any{"v": "V"}}, root: func(j *J) {
			j.Project(ProjectProps{Folder: "app"}, func(j *J) {
				j.Folder("x", func(j *J) {
					j.Folder("y", func(j *J) {
						j.File("n.txt", func(j *J) { j.Content("N") })
					})
				})
				j.CopyFiles(CopyFilesProps{From: "/src/tree", To: "c"})
				j.CopyFiles(CopyFilesProps{From: "/src/tree/t.txt", To: "one.txt"})
				j.Inject("j.txt", func(j *J) { j.Content("J") })
			})
		}},
	},
	"merge_marker_clean": func() []parityStep {
		merge := true
		opts := Options{Existing: Existing{Txt: ExistingTxt{Merge: &merge}}}
		doc := func(v string) func(*J) {
			return parityOne("doc.md", "How a conflict looks:\n>>>>>>> EXISTING: "+
				"2020-01-01T00:00:00.000Z/merge\n"+v+"\n")
		}
		return []parityStep{{opts: opts, root: doc("v1")},
			{opts: opts, root: doc("v2")}, {opts: opts, root: doc("v3")}}
	}(),
	"merge_unresolved": func() []parityStep {
		merge := true
		opts := Options{Existing: Existing{Txt: ExistingTxt{Merge: &merge}}}
		return []parityStep{
			{root: parityOne("a.txt", "A\n")},
			{edit: func(m *MemFS) { _ = m.WriteFile("/out/app/a.txt", []byte("A\nuser\n")) }},
			{opts: opts, root: parityOne("a.txt", "A\ngen\n")},
			{opts: opts, root: parityOne("a.txt", "A\ngen2\n")},
		}
	}(),
}

func TestParityRuns(t *testing.T) {
	for name, steps := range parityRuns {
		t.Run(name, func(t *testing.T) {
			body, err := parityFS.ReadFile("testdata/parity/" + name + ".json")
			if err != nil {
				t.Fatal(err)
			}
			var want struct {
				Runs []struct {
					Files Files `json:"files"`
					Audit []any `json:"audit"`
				} `json:"runs"`
				Vol map[string]corpusBytes `json:"vol"`
			}
			if err := json.Unmarshal(body, &want); err != nil {
				t.Fatal(err)
			}
			mem := NewMemFS()
			i := 0
			for _, st := range steps {
				if st.edit != nil {
					st.edit(mem)
					continue
				}
				res, err := New(WithFS(mem), WithFolder("/out"),
					WithNow(func() int64 { return frozenNow })).Generate(st.opts, st.root)
				if err != nil {
					t.Fatal(err)
				}
				if i >= len(want.Runs) {
					t.Fatalf("more generates than TS recorded")
				}
				assertFiles(t, res.Files, want.Runs[i].Files)
				assertAudit(t, res.Audit(), want.Runs[i].Audit)
				i++
			}
			if i != len(want.Runs) {
				t.Fatalf("%d generates, TS recorded %d", i, len(want.Runs))
			}
			assertVol(t, mem, want.Vol)
		})
	}
}
